import{_ as t,o,c as a,a5 as d}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"FR 3.7.4 — Upload Brand Knowledge Document","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/06-ai-features/3-7-4-upload-brand-knowledge-document/spec.md","filePath":"feature/srs/06-ai-features/3-7-4-upload-brand-knowledge-document/spec.md"}'),n={name:"feature/srs/06-ai-features/3-7-4-upload-brand-knowledge-document/spec.md"};function c(r,e,i,s,l,g){return o(),a("div",null,[...e[0]||(e[0]=[d('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-7-4-—-upload-brand-knowledge-document" tabindex="-1">FR 3.7.4 — Upload Brand Knowledge Document <a class="header-anchor" href="#fr-3-7-4-—-upload-brand-knowledge-document" aria-label="Permalink to &quot;FR 3.7.4 — Upload Brand Knowledge Document&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.7.4</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-091</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">Upload Brand Knowledge Document</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">AI Features (<code>3.7</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-20</code>, <code>BR-46</code>, <code>BR-47</code></td></tr><tr><td style="text-align:left;"><strong>Message Codes</strong></td><td style="text-align:left;"><code>MSG01</code>, <code>MSG02</code>, <code>MSG03</code>, <code>MSG07</code>, <code>MSG14</code></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-business-value" tabindex="-1">1. Objective &amp; Business Value <a class="header-anchor" href="#_1-objective-business-value" aria-label="Permalink to &quot;1. Objective &amp; Business Value&quot;">​</a></h2><p>Allow <code>Owner</code>, <code>Manager</code>, and <code>Client</code> actors in a Workspace to upload official Brand Guidelines, product catalogs, and tone-of-voice playbooks (<code>PDF</code>, <code>DOCX</code>, <code>TXT</code>, <code>MD</code>) into the Workspace Brand Knowledge Base (<code>BR-46</code>, <code>BR-47</code>). Uploaded files are virus/MIME-validated, stored in S3 under the workspace namespace, parsed, chunked with overlap, embedded, and indexed into ChromaDB (<code>brand_docs_{workspace_id}</code>) so downstream AI generation stays strictly grounded in factual brand data.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an <code>Owner</code>, <code>Manager</code>, or <code>Client</code>, I want to upload Brand Knowledge documents into my Workspace so that AI-generated captions, product descriptions, and creative prompts accurately reflect official product specs, brand voice, and mandatory disclaimers without hallucination.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Role &amp; Workspace Scope (<code>BR-20</code>):</strong> Only <code>Owner</code>, <code>Manager</code>, and <code>Client</code> members of <code>{workspaceId}</code> may upload Brand Knowledge documents; <code>Creator</code> and non-members receive <code>403 FORBIDDEN</code> (<code>MSG07</code>).</li><li><strong>File Format, Magic-Byte &amp; Size Validation (<code>BR-47</code>):</strong> Accepts <code>.pdf</code>, <code>.docx</code>, <code>.txt</code>, and <code>.md</code> up to <code>20 MB</code> per file (and within Agency plan storage/document entitlements). Executables, macro-enabled <code>.docm</code>, password-encrypted PDFs, empty (<code>0 byte</code>) files, or image-only scanned PDFs with zero extractable text are rejected deterministically (<code>MSG02</code>, <code>MSG14</code>).</li><li><strong>Chunking &amp; Vector Ingestion Pipeline:</strong> <code>brandhub-ai-service</code> (<code>app/api/v1/endpoints/rag.py</code>, <code>app/utils/extractor.py</code>, <code>VectorStoreService</code>) extracts UTF-8 NFC normalized text, splits into <code>500–800</code> token semantic chunks (<code>100</code> token overlap), computes embeddings, and upserts vectors tagged with <code>{workspace_id, document_id, filename, chunk_index}</code> into ChromaDB collection <code>brand_docs_{workspace_id}</code>.</li><li><strong>Atomic Rollback on Failure:</strong> If text extraction or ChromaDB upsert fails, partial chunks for <code>document_id</code> are purged and document status is marked <code>FAILED</code> with actionable error code (<code>MSG03</code>) rather than leaving ghost vectors.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Upload dropzone, file size/type hints, progress bar, and validation error messages use key-parallel <code>aiStudio.knowledgeBase.upload.*</code> keys in <code>vi.json</code> and <code>en.json</code>.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> Dropzone hover/drag states, file queue cards, and progress indicators adhere to semantic Light/Dark theme tokens.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Surface:</strong> <code>/workspaces/:workspaceId/ai-studio/knowledge-base</code> upload dialog &amp; dropzone (<code>pages/ai-studio/knowledge-base/index.tsx</code>).</li><li><strong>UI States:</strong><ul><li><strong>Idle / Drag-Over:</strong> Clear MIME &amp; <code>20 MB</code> limit hint; accessible keyboard file trigger.</li><li><strong>Uploading &amp; Embedding:</strong> Determinate upload progress followed by <code>PENDING -&gt; INDEXED</code> vectorization badge; upload button disabled against double-submit.</li><li><strong>Success:</strong> Toast notification showing extracted <code>chunkCount</code> + automatic <code>TanStack Query</code> invalidation of FR 3.7.3 document list.</li><li><strong>Error:</strong> Inline per-file rejection reason (oversize, unsupported format, scanned PDF with no text).</li></ul></li></ul><h2 id="_5-api-contract" tabindex="-1">5. API Contract <a class="header-anchor" href="#_5-api-contract" aria-label="Permalink to &quot;5. API Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method &amp; Endpoint</th><th style="text-align:left;">Auth</th><th style="text-align:left;">Request</th><th style="text-align:left;">Response</th></tr></thead><tbody><tr><td style="text-align:left;"><code>POST /api/v1/workspaces/{workspaceId}/ai/knowledge/documents</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Client</code>)</td><td style="text-align:left;"><code>multipart/form-data</code> (<code>file</code>, optional <code>category</code>, <code>title</code>)</td><td style="text-align:left;"><code>201 ApiResponse&lt;BrandDocumentResponse&gt;</code></td></tr><tr><td style="text-align:left;"><code>POST /api/v1/ai/rag/documents</code></td><td style="text-align:left;"><code>X-Internal-Api-Key</code> (<code>business -&gt; ai</code>)</td><td style="text-align:left;"><code>RagDocumentIngestRequest</code> (S3 key / bytes + <code>workspace_id</code> + <code>document_id</code>)</td><td style="text-align:left;"><code>200 RagIngestResult</code> (<code>chunk_count</code>, <code>collection_name</code>)</td></tr></tbody></table><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><code>PAYLOAD_TOO_LARGE</code> (<code>413</code>, <code>MSG14</code>): File exceeds <code>20 MB</code> limit or Agency storage quota (<code>agency_storage_usage</code>).</li><li><code>UNSUPPORTED_DOCUMENT_FORMAT</code> (<code>415</code> / <code>400</code>, <code>MSG02</code>): Disallowed extension or mismatched magic bytes.</li><li><code>EMPTY_EXTRACTABLE_TEXT</code> (<code>422</code>, <code>MSG02</code>): Scanned image PDF without OCR text layer; returns clear localized instruction to upload searchable PDF/DOCX/TXT.</li><li><strong>Duplicate Filename in Same Workspace:</strong> Preserves distinct <code>documentId</code> or prompts version replacement without corrupting existing chunks.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Sibling SRS FRs:</strong> <a href="./../3-7-3-view-brand-knowledge-documents/spec.html">FR 3.7.3 — View Brand Knowledge Documents</a> · <a href="./../3-7-5-delete-brand-knowledge-document/spec.html">FR 3.7.5 — Delete Brand Knowledge Document</a> · <a href="./../3-7-6-generate-caption/spec.html">FR 3.7.6 — Generate Caption</a></li><li><strong>Consolidated Extension Module:</strong> <a href="./../../../modules/05-ai-rag-and-crawler/rag-caption-moderation-and-humanizer/spec.html"><code>rag-caption-moderation-and-humanizer</code></a></li><li><strong>BA Domain Baseline:</strong> <a href="./../../../../ba/06-ai-features.html">BA 3.7 AI Features</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Multipart validation, S3 persistence, text extraction (<code>PDF/DOCX/TXT/MD</code>), ChromaDB <code>brand_docs_{workspace_id}</code> indexing, rollback cleanup, <code>vi</code>/<code>en</code> i18n, and Light/Dark UI verified against <a href="./test.html">test.md</a>.</li><li><strong>Out of Scope:</strong> Optical Character Recognition (OCR) on handwritten/scanned image PDFs; copyright/plagiarism scanning (explicitly de-scoped in SRS).</li></ul>',19)])])}const m=t(n,[["render",c]]);export{u as __pageData,m as default};
